-- C1 MATERIAL PAYMENT CONCURRENCY FIXTURE
begin;
-- The proposal keeps null revision pointers so cleanup never has to break a proposal/revision foreign-key cycle.
-- The legacy evidence gate admits a direct insert only for the file id named by the material intent setting.
do $$
declare v_file record;
begin
  for v_file in
    select file_row.id, file_row.hash_seed, file_row.filename, file_row.uploaded_by
    from (values
      ('c1400000-0000-4000-8000-000000000501'::uuid,501,'c140-unsigned-quotation-x.pdf','c1400000-0000-4000-8000-000000000906'::uuid),
      ('c1400000-0000-4000-8000-000000000502'::uuid,502,'c140-unsigned-quotation-y.pdf','c1400000-0000-4000-8000-000000000906'::uuid),
      ('c1400000-0000-4000-8000-000000000511'::uuid,511,'c140-signed-contract-x.pdf','c1400000-0000-4000-8000-000000000903'::uuid),
      ('c1400000-0000-4000-8000-000000000512'::uuid,512,'c140-signed-quotation-x.pdf','c1400000-0000-4000-8000-000000000903'::uuid),
      ('c1400000-0000-4000-8000-000000000513'::uuid,513,'c140-signed-contract-y.pdf','c1400000-0000-4000-8000-000000000903'::uuid),
      ('c1400000-0000-4000-8000-000000000514'::uuid,514,'c140-signed-quotation-y.pdf','c1400000-0000-4000-8000-000000000903'::uuid),
      ('c1400000-0000-4000-8000-000000000521'::uuid,521,'c140-amendment-x.pdf','c1400000-0000-4000-8000-000000000903'::uuid),
      ('c1400000-0000-4000-8000-000000000531'::uuid,531,'c140-transfer-proof-a.pdf','c1400000-0000-4000-8000-000000000904'::uuid),
      ('c1400000-0000-4000-8000-000000000532'::uuid,532,'c140-transfer-proof-b.pdf','c1400000-0000-4000-8000-000000000905'::uuid)
    ) as file_row(id,hash_seed,filename,uploaded_by)
  loop
    perform pg_catalog.set_config('taskovia.c1_material_evidence.intent', v_file.id::text, true);
      id,tenant_id,company_id,project_id,object_path,original_filename,
      declared_mime_type,declared_size_bytes,declared_sha256,
      verified_mime_type,verified_size_bytes,verified_sha256,status,intent_expires_at,
      created_by,finalized_by,finalized_at,version
    ) values (
      v_file.id,'c1400000-0000-4000-8000-000000000010','c1400000-0000-4000-8000-000000000020','c1400000-0000-4000-8000-000000000101',
      'c1400000-0000-4000-8000-000000000010/c1400000-0000-4000-8000-000000000020/c1400000-0000-4000-8000-000000000101/'||v_file.id::text,
      v_file.filename,'application/pdf',8,lpad(to_hex(v_file.hash_seed),64,'0'),'application/pdf',8,lpad(to_hex(v_file.hash_seed),64,'0'),'finalized',
      now()+interval '15 minutes',v_file.uploaded_by,v_file.uploaded_by,now(),1
    );
  end loop;
  perform pg_catalog.set_config('taskovia.c1_material_evidence.intent', '', true);
end;
$$;
-- Contract X (installment a01 = 100) backs the request and amendment races; contract Y (installment a02 = 60) backs the pay race.
set local role authenticated;
select pg_catalog.set_config('request.jwt.claims','{"sub":"c1400000-0000-4000-8000-000000000903","role":"authenticated"}',true);
select public.c1_material_record_contract('c1400000-0000-4000-8000-000000000020','c1400000-0000-4000-8000-000000000101','c1400000-0000-4000-8000-000000000351','{"expectedOrderVersion":1,"contractNo":"C140-HD-X","signedOn":"2026-10-01","subtotal":"100.0000","vatAmount":"0.0000","total":"100.0000","varianceReason":null,"contractFileId":"c1400000-0000-4000-8000-000000000511","signedQuotationFileId":"c1400000-0000-4000-8000-000000000512","installments":[{"installmentKey":"c1400000-0000-4000-8000-000000000a01","name":"C140 Dot X","amount":"100.0000","dueOn":"2026-12-01","isAdvance":true}]}','c1400000-0000-4000-8000-000000000601','c1400000-0000-4000-8000-000000000701');
select public.c1_material_record_contract('c1400000-0000-4000-8000-000000000020','c1400000-0000-4000-8000-000000000101','c1400000-0000-4000-8000-000000000352','{"expectedOrderVersion":1,"contractNo":"C140-HD-Y","signedOn":"2026-10-01","subtotal":"60.0000","vatAmount":"0.0000","total":"60.0000","varianceReason":null,"contractFileId":"c1400000-0000-4000-8000-000000000513","signedQuotationFileId":"c1400000-0000-4000-8000-000000000514","installments":[{"installmentKey":"c1400000-0000-4000-8000-000000000a02","name":"C140 Dot Y","amount":"60.0000","dueOn":"2026-12-01","isAdvance":true}]}','c1400000-0000-4000-8000-000000000602','c1400000-0000-4000-8000-000000000702');
set local role none;
select pg_catalog.set_config('taskovia.c140_fixture.contract_x',(select contract.id::text from public.material_contracts as contract where contract.tenant_id='c1400000-0000-4000-8000-000000000010' and contract.company_id='c1400000-0000-4000-8000-000000000020' and contract.project_id='c1400000-0000-4000-8000-000000000101' and contract.order_id='c1400000-0000-4000-8000-000000000351'),true);
select pg_catalog.set_config('taskovia.c140_fixture.contract_y',(select contract.id::text from public.material_contracts as contract where contract.tenant_id='c1400000-0000-4000-8000-000000000010' and contract.company_id='c1400000-0000-4000-8000-000000000020' and contract.project_id='c1400000-0000-4000-8000-000000000101' and contract.order_id='c1400000-0000-4000-8000-000000000352'),true);
-- The pay race needs one approved request on contract Y: accountant A submits, treasurer A approves.
set local role authenticated;
select pg_catalog.set_config('request.jwt.claims','{"sub":"c1400000-0000-4000-8000-000000000901","role":"authenticated"}',true);
select public.c1_material_create_payment_request('c1400000-0000-4000-8000-000000000020','c1400000-0000-4000-8000-000000000101',pg_catalog.current_setting('taskovia.c140_fixture.contract_y')::uuid,'{"installmentKey":"c1400000-0000-4000-8000-000000000a02","amount":"60.0000","invoiceIds":[],"note":"C140 pay race request"}','c1400000-0000-4000-8000-000000000603','c1400000-0000-4000-8000-000000000703');
set local role none;
select pg_catalog.set_config('taskovia.c140_fixture.request_y',(select request.id::text from public.material_payment_requests as request where request.tenant_id='c1400000-0000-4000-8000-000000000010' and request.company_id='c1400000-0000-4000-8000-000000000020' and request.project_id='c1400000-0000-4000-8000-000000000101' and request.installment_key='c1400000-0000-4000-8000-000000000a02'),true);
set local role authenticated;
select pg_catalog.set_config('request.jwt.claims','{"sub":"c1400000-0000-4000-8000-000000000904","role":"authenticated"}',true);
select public.c1_material_decide_payment_request('c1400000-0000-4000-8000-000000000020','c1400000-0000-4000-8000-000000000101',pg_catalog.current_setting('taskovia.c140_fixture.request_y')::uuid,'{"expectedVersion":1,"decision":"approve"}','c1400000-0000-4000-8000-000000000604','c1400000-0000-4000-8000-000000000704');
set local role none;
commit;
